args.content:
/**
 * Regression check for "typescript-export-types":
 * the published TS surface must export the correctly-spelled axis component
 * option aliases and the calendar/matrix coordinate-system mixins.
 * Checked with: npx tsc --noEmit --strict agent_tests/typescript-export-types/check-types.ts
 * (run from the repo root; module resolution picks up src/).
 */
import {
    XAxisComponentOption,
    YAxisComponentOption,
    XAXisComponentOption,
    YAXisComponentOption,
    EChartsOption
} from '../../src/export/option';
import {
    ComponentOnCalendarOptionMixin,
    ComponentOnMatrixOptionMixin,
    SeriesOnRadarOptionMixin,
    SeriesOnCalendarOptionMixin // deprecated alias, kept for compatibility
} from '../../src/util/types';

const xAxis: XAxisComponentOption = {type: 'category'};
const yAxis: YAxisComponentOption = {type: 'value'};
// Old misspelled aliases still refer to the same types.
const xAxisOld: XAXisComponentOption = xAxis;
const yAxisOld: YAXisComponentOption = yAxis;

// Ids accept both string and number (OptionId).
const onCalendar: ComponentOnCalendarOptionMixin = {calendarIndex: 0, calendarId: 1};
const onMatrix: ComponentOnMatrixOptionMixin = {matrixIndex: 0, matrixId: 'm'};
const onRadar: SeriesOnRadarOptionMixin = {radarIndex: 0, radarId: 2};
const onCalendarLegacy: SeriesOnCalendarOptionMixin = onCalendar;

const option: EChartsOption = {
    xAxis,
    yAxis,
    series: []
};

export {
    xAxisOld, yAxisOld, onCalendar, onMatrix, onRadar, onCalendarLegacy, option
};

